     1|/**
     2| * IVX Runtime Variables manager (owner-only).
     3| *
     4| * Makes every required credential/variable VISIBLE, status-classified, masked,
     5| * and VERIFIABLE from the owner dashboard — without ever returning a secret
     6| * value to the client. It introspects the backend runtime env (`process.env`),
     7| * classifies each variable into the owner's exact status vocabulary, and runs
     8| * REAL verification probes for the credentials that can be checked over HTTPS
     9| * (GitHub, Render, Supabase anon + service role, production /health).
    10| *
    11| * Security:
    12| * - NEVER returns a secret value. Present values are masked (first 3 + last 2,
    13| *   short values fully masked) so the owner can confirm WHICH value is set
    14| *   without exposing it.
    15| * - Verification probes return pass/fail + HTTP status only, never the value.
    16| *
    17| * Honesty:
    18| * - `knownInRork` is derived from the project's declared Rork env panel so the
    19| *   "present in Rork but not injected into this runtime" case is reported
    20| *   exactly (`PRESENT_IN_RORK_NOT_INJECTED`) instead of a generic "missing".
    21| * - Credentials without a safe live probe (AWS, AI gateway, owner token) are
    22| *   validated by presence + format and labeled honestly — never claimed VERIFIED.
    23| */
    24|
    25|export const IVX_RUNTIME_VARIABLES_MARKER = 'ivx-runtime-variables-2026-06-04';
    26|
    27|export type VarScope = 'client' | 'server' | 'build' | 'runtime' | 'sandbox';
    28|
    29|export type VarStatus =
    30|  | 'MISSING_FROM_RORK'
    31|  | 'PRESENT_IN_RORK_NOT_INJECTED'
    32|  | 'PRESENT_IN_RUNTIME'
    33|  | 'PRESENT_BUT_INVALID'
    34|  | 'PRESENT_BUT_UNAUTHORIZED'
    35|  | 'VERIFIED';
    36|
    37|export type VarVerifyKind =
    38|  | 'github'
    39|  | 'render'
    40|  | 'supabase_anon'
    41|  | 'supabase_service'
    42|  | 'ai_gateway'
    43|  | 'aws'
    44|  | 'production'
    45|  | 'owner_token'
    46|  | 'format_only';
    47|
    48|export type RuntimeVariableSpec = {
    49|  /** Canonical variable name. */
    50|  name: string;
    51|  /** Alternative env names that satisfy this variable (first present wins). */
    52|  aliases: string[];
    53|  isPublic: boolean;
    54|  scopes: VarScope[];
    55|  usedBy: string[];
    56|  verify: VarVerifyKind;
    57|  /** Declared in the project's Rork env panel (public or private list). */
    58|  knownInRork: boolean;
    59|  /** Honest one-line description of the variable's role. */
    60|  description: string;
    61|};
    62|
    63|export type RuntimeVariableStatus = {
    64|  name: string;
    65|  aliases: string[];
    66|  isPublic: boolean;
    67|  scopes: VarScope[];
    68|  usedBy: string[];
    69|  verifyKind: VarVerifyKind;
    70|  knownInRork: boolean;
    71|  description: string;
    72|  /** Which env key actually carried the value (name or an alias), if present. */
    73|  resolvedFrom: string | null;
    74|  present: boolean;
    75|  masked: string | null;
    76|  /** Length of the resolved value (0 when absent) — never the value itself. */
    77|  valueLength: number;
    78|  status: VarStatus;
    79|  /** True for EXPO_PUBLIC_* / VITE_* / RORK_PUBLIC_* — inlined into the client bundle. */
    80|  publicWarning: boolean;
    81|  lastVerifiedAt: string | null;
    82|  verifyDetail: string | null;
    83|};
    84|
    85|export type RuntimeVariablesReport = {
    86|  marker: string;
    87|  generatedAt: string;
    88|  /** Where this introspection ran (helps the owner read scope correctly). */
    89|  runtimeLabel: string;
    90|  total: number;
    91|  present: number;
    92|  missing: number;
    93|  variables: RuntimeVariableStatus[];
    94|};
    95|
    96|type EnvSnapshot = Record<string, string | undefined>;
    97|type FetchLike = (input: string, init?: RequestInit) => Promise<Response>;
    98|
    99|function trimmed(value: string | undefined): string {
   100|  return typeof value === 'string' ? value.trim() : '';
   101|}
   102|
   103|function resolveValue(env: EnvSnapshot, spec: RuntimeVariableSpec): { from: string | null; value: string } {
   104|  for (const key of [spec.name, ...spec.aliases]) {
   105|    const value = trimmed(env[key]);
   106|    if (value.length > 0) return { from: key, value };
   107|  }
   108|  return { from: null, value: '' };
   109|}
   110|
   111|/** Mask a secret: first 3 + last 2 visible, short values fully masked. Never the raw value. */
   112|export function maskSecret(value: string): string {
   113|  const len = value.length;
   114|  if (len === 0) return '';
   115|  if (len <= 6) return '*'.repeat(len);
   116|  return `${value.slice(0, 3)}${'*'.repeat(Math.max(4, len - 5))}${value.slice(-2)}`;
   117|}
   118|
   119|/** True for client-inlined public variables (EXPO_PUBLIC_ / VITE_ / RORK_PUBLIC_). */
   120|export function isPublicClientVar(name: string): boolean {
   121|  return /^(EXPO_PUBLIC_|VITE_|RORK_PUBLIC_)/.test(name);
   122|}
