   427|function splitSqlDefinitionItems(body: string): string[] {
   428|  const items: string[] = [];
   429|  let current = '';
   430|  let depth = 0;
   431|  let inSingleQuote = false;
   432|  let inDoubleQuote = false;
   433|  for (let index = 0; index < body.length; index += 1) {
   434|    const character = body[index] ?? '';
   435|    const nextCharacter = body[index + 1] ?? '';
   436|    current += character;
   437|    if (inSingleQuote) {
   438|      if (character === "'" && nextCharacter === "'") {
   439|        current += nextCharacter;
   440|        index += 1;
   441|        continue;
   442|      }
   443|      if (character === "'") {
   444|        inSingleQuote = false;
   445|      }
   446|      continue;
   447|    }
   448|    if (inDoubleQuote) {
   449|      if (character === '"') {
   450|        inDoubleQuote = false;
   451|      }
   452|      continue;
   453|    }
   454|    if (character === "'") {
   455|      inSingleQuote = true;
   456|      continue;
   457|    }
   458|    if (character === '"') {
   459|      inDoubleQuote = true;
   460|      continue;
   461|    }
   462|    if (character === '(') {
   463|      depth += 1;
   464|      continue;
   465|    }
   466|    if (character === ')') {
   467|      depth = Math.max(0, depth - 1);
   468|      continue;
   469|    }
   470|    if (character === ',' && depth === 0) {
   471|      items.push(current.slice(0, -1).trim());
   472|      current = '';
   473|    }
   474|  }
   475|  const finalItem = current.trim();
   476|  if (finalItem) {
   477|    items.push(finalItem);
   478|  }
   479|  return items;
